from itertools import permutations

n = 7
# Find Latin square with diagonal x[i][i]=i and x[x[i][j]][x[j][i]] = i

# Use constraint backtracking
import sys
sys.setrecursionlimit(100000)

x = [[-1]*n for _ in range(n)]
row_used = [set() for _ in range(n)]
col_used = [set() for _ in range(n)]

for i in range(n):
    x[i][i] = i
    row_used[i].add(i)
    col_used[i].add(i)

cells = [(i,j) for i in range(n) for j in range(n) if i!=j]

solutions = []

def check_qg3_partial():
    # check all filled (i,j) where x[i][j] and x[j][i] both known
    for i in range(n):
        for j in range(n):
            a = x[i][j]
            b = x[j][i]
            if a>=0 and b>=0:
                c = x[a][b]
                if c>=0 and c != i:
                    return False
    return True

def backtrack(idx):
    if idx == len(cells):
        if check_qg3_partial():
            solutions.append([row[:] for row in x])
            return True
        return False
    i,j = cells[idx]
    if x[i][j] != -1:
        return backtrack(idx+1)
    for v in range(n):
        if v in row_used[i] or v in col_used[j]:
            continue
        x[i][j] = v
        row_used[i].add(v)
        col_used[j].add(v)
        # partial check
        ok = True
        # check constraint involving (i,j)
        # for each pair (i,j), if x[j][i] known, and x[v][x[j][i]] known, must equal i
        b = x[j][i]
        if b >= 0:
            c = x[v][b]
            if c >= 0 and c != i:
                ok = False
        # also we may be the x[j][i] for pair (j,i): x[x[j][i]][x[i][j]]=j
        if ok:
            a2 = x[j][i]
            if a2 >= 0:
                c = x[a2][v]
                if c >= 0 and c != j:
                    ok = False
        # also, our cell could be x[a][b] for some pair (p,q) with x[p][q]=i, x[q][p]=j -> but that's i,j themselves
        # constraint: x[x[p][q]][x[q][p]]=p. If x[p][q]=i and x[q][p]=j, then x[i][j]=p, so p=v. 
        # So for any p,q with x[p][q]=i and x[q][p]=j, need v=p.
        if ok:
            for p in range(n):
                for q in range(n):
                    if x[p][q]==i and x[q][p]==j:
                        if v != p:
                            ok = False
                            break
                if not ok: break
        if ok:
            if backtrack(idx+1):
                return True
        x[i][j] = -1
        row_used[i].discard(v)
        col_used[j].discard(v)
    return False

